/**
 * TIN encryption key startup check.
 *
 * Called before any W-9 write to verify the GUC app.settings.tin_encryption_key
 * is configured in the database. If missing, returns a 503 so the client can
 * surface a clear error rather than a cryptic pgcrypto failure.
 *
 * The check performs a dry pgp_sym_encrypt on a dummy string — it never touches
 * real TIN data and never logs the key value.
 */

import { createServiceRoleClient } from '@/lib/supabase/server'
import { logger } from '@/lib/logger'

const TIN_KEY_SENTINEL = '__tin_key_check__'

let _checked = false
let _available = false

/**
 * Returns true if the TIN encryption key GUC is configured.
 * Result is cached for the process lifetime.
 */
export async function isTinKeyAvailable(): Promise<boolean> {
  if (_checked) return _available

  try {
    const admin = createServiceRoleClient()
    // Attempt a dry encrypt — if key is unset, Postgres raises an error
    const { error } = await admin.rpc('set_artist_tax_info', {
      p_artist_id: TIN_KEY_SENTINEL,
      p_tin_type: 'other' as const,
      p_tin_plaintext: '0000',
    })

    // We expect an error here (artist_id won't exist) — the key question is
    // whether the error is a pgcrypto "key not configured" error or an expected
    // FK violation. A pgcrypto error message contains "undefined" for the GUC.
    if (error) {
      const isKeyError =
        error.message.includes('unrecognized configuration parameter') ||
        error.message.includes('tin_encryption_key') ||
        error.message.includes('configuration parameter')

      if (isKeyError) {
        logger.error({ err: error }, 'TIN encryption key GUC not configured')
        _checked = true
        _available = false
        return false
      }
    }

    _checked = true
    _available = true
    return true
  } catch (err) {
    logger.error({ err }, 'TIN key availability check failed unexpectedly')
    _checked = true
    _available = false
    return false
  }
}

/**
 * Returns a 503 Response if TIN encryption is not configured.
 * Call at the top of any API route that writes W-9 data.
 *
 * @example
 * const keyGuard = await requireTinKey()
 * if (keyGuard) return keyGuard
 */
export async function requireTinKey(): Promise<Response | null> {
  const available = await isTinKeyAvailable()
  if (available) return null

  return Response.json(
    {
      error:
        'TIN encryption key not configured. Set DB GUC `app.settings.tin_encryption_key` before collecting W-9s.',
      docs: 'Add TIN_ENCRYPTION_KEY to your environment and run: ALTER DATABASE postgres SET app.settings.tin_encryption_key = \'your-32-char-key\';',
    },
    { status: 503 },
  )
}

/**
 * Payroll utility helpers — formatting, sanitization, date helpers.
 * All are pure functions with no side effects.
 */

/**
 * Format a payroll period as "Mar 2026" from an ISO date string.
 */
export function formatPeriodMonth(isoDate: string): string {
  return new Date(isoDate + 'T00:00:00').toLocaleDateString('en-US', {
    month: 'short',
    year: 'numeric',
  })
}

/**
 * Format a date range as "Mar 1 – Mar 31, 2026".
 */
export function formatPeriodRange(start: string, end: string): string {
  const s = new Date(start + 'T00:00:00')
  const e = new Date(end + 'T00:00:00')
  const sameYear = s.getFullYear() === e.getFullYear()
  const sameMonth = sameYear && s.getMonth() === e.getMonth()

  const startStr = s.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  const endStr = e.toLocaleDateString('en-US', {
    month: sameMonth ? undefined : 'short',
    day: 'numeric',
    year: 'numeric',
  })
  return `${startStr} – ${endStr}`
}

/**
 * Format a relative date for display.
 * Returns "Today", "Yesterday", "Apr 1", or "Apr 1, 2025".
 */
export function formatRelativeDate(isoDate: string | null | undefined): string {
  if (!isoDate) return '—'
  const d = new Date(isoDate)
  const now = new Date()
  const diffDays = Math.floor((now.getTime() - d.getTime()) / 86_400_000)
  if (diffDays === 0) return 'Today'
  if (diffDays === 1) return 'Yesterday'
  if (diffDays < 365) return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })
}

/**
 * Sanitize a TIN plaintext before passing to RPC.
 * Strips dashes, spaces. Never logs the value.
 */
export function sanitizeTin(raw: string): string {
  return raw.replace(/[-\s]/g, '').trim()
}

/**
 * Format an address object as a one-line string.
 */
export function formatAddress(address: Record<string, string> | null | undefined): string {
  if (!address) return '—'
  const parts = [
    address['street'],
    address['city'],
    [address['state'], address['zip']].filter(Boolean).join(' '),
    address['country'],
  ].filter(Boolean)
  return parts.join(', ')
}

/**
 * Returns the first day of last month as ISO "YYYY-MM-DD".
 */
export function lastMonthStart(): string {
  const d = new Date()
  d.setDate(1)
  d.setMonth(d.getMonth() - 1)
  return d.toISOString().slice(0, 10)
}

/**
 * Returns the last day of last month as ISO "YYYY-MM-DD".
 */
export function lastMonthEnd(): string {
  const d = new Date()
  d.setDate(0) // last day of prior month
  return d.toISOString().slice(0, 10)
}

/**
 * Returns true if current month is January.
 */
export function isJanuary(): boolean {
  return new Date().getMonth() === 0
}

/**
 * Current calendar year.
 */
export function currentYear(): number {
  return new Date().getFullYear()
}

/**
 * Year options for tax year selectors: current year + last 3.
 */
export function taxYearOptions(): number[] {
  const y = currentYear()
  return [y, y - 1, y - 2, y - 3]
}

/**
 * Format a run label from period start, falling back to period month.
 */
export function runLabel(label: string | null, periodStart: string): string {
  return label ?? formatPeriodMonth(periodStart)
}

import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

const CreateRunSchema = z.object({
  period_start: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Invalid date format'),
  period_end: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Invalid date format'),
  label: z.string().max(80).optional().nullable(),
})

export async function GET(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No studio membership' }, { status: 403 })

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const guard = requireFeature(plan, 'payroll')
  if (guard) return guard

  const url = new URL(req.url)
  const status = url.searchParams.get('status')
  const year = url.searchParams.get('year')

  let query = supabase
    .from('payroll_runs')
    .select('*')
    .eq('studio_id', member.studio_id)
    .order('period_start', { ascending: false })

  if (status && status !== 'all') {
    query = query.eq('status', status)
  }
  if (year) {
    query = query
      .gte('period_start', `${year}-01-01`)
      .lte('period_start', `${year}-12-31`)
  }

  const { data, error } = await query
  if (error) {
    logger.error({ err: error, studioId: member.studio_id }, 'payroll runs list failed')
    return Response.json({ error: 'Failed to load payroll runs' }, { status: 500 })
  }

  return Response.json({ data })
}

export async function POST(req: NextRequest) {
  const supabase = await createClient()
  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
