import { NextRequest } from 'next/server'
import { z } from 'zod'
import { createClient } from '@/lib/supabase/server'
import { requireFeature } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

const PreviewSchema = z.object({
  period_start: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Invalid date format'),
  period_end: z.string().regex(/^\d{4}-\d{2}-\d{2}$/, 'Invalid date format'),
})

export async function POST(req: NextRequest) {
  const supabase = await createClient()

  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No studio membership' }, { status: 403 })

  if (member.role !== 'owner' && member.role !== 'admin') {
    return Response.json({ error: 'Only owners and admins can preview payroll' }, { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const guard = requireFeature(plan, 'payroll')
  if (guard) return guard

  const body = PreviewSchema.safeParse(await req.json())
  if (!body.success) return Response.json({ error: body.error.flatten() }, { status: 400 })

  if (body.data.period_start >= body.data.period_end) {
    return Response.json({ error: 'period_end must be after period_start' }, { status: 400 })
  }

  // Read-only: aggregate SELECT from commission_records for the period.
  // No mutations. This powers the Step 2 preview in the new-run wizard.
  const { data, error } = await supabase
    .from('commission_records')
    .select(`
      artist_id,
      artists!inner(id, full_name, avatar_url),
      net_artist_payout,
      status
    `)
    .eq('studio_id', member.studio_id)
    .in('status', ['approved', 'finalized'])
    .gte('appointment_date', body.data.period_start)
    .lte('appointment_date', body.data.period_end)
    .is('payroll_run_id', null)

  if (error) {
    logger.error({ err: error, studioId: member.studio_id }, 'payroll preview query failed')
    return Response.json({ error: 'Failed to load payroll preview' }, { status: 500 })
  }

  // Aggregate by artist
  const byArtist = new Map<string, {
    artist_id: string
    full_name: string | null
    avatar_url: string | null
    record_count: number
    total_cents: number
  }>()

  for (const row of data ?? []) {
    const existing = byArtist.get(row.artist_id)
    const artist = Array.isArray(row.artists) ? row.artists[0] : row.artists
    if (existing) {
      existing.record_count++
      existing.total_cents += row.net_artist_payout ?? 0
    } else {
      byArtist.set(row.artist_id, {
        artist_id: row.artist_id,
        full_name: artist?.full_name ?? null,
        avatar_url: artist?.avatar_url ?? null,
        record_count: 1,
        total_cents: row.net_artist_payout ?? 0,
      })
    }
  }

  const artists = Array.from(byArtist.values()).sort((a, b) => b.total_cents - a.total_cents)
  const total_cents = artists.reduce((sum, a) => sum + a.total_cents, 0)
  const record_count = artists.reduce((sum, a) => sum + a.record_count, 0)

  return Response.json({
    data: {
      artists,
      total_cents,
      record_count,
      period_start: body.data.period_start,
      period_end: body.data.period_end,
    },
  })
}

