import { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { requireFeature } from '@/lib/billing/feature-gate'
import { requireTinKey } from '@/lib/payroll/check-tin-key'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import type { PlanTier } from '@/lib/billing/feature-gate'

interface RouteContext {
  params: Promise<{ id: string }>
}

/**
 * POST /api/tax-info/artists/[id]/decrypt
 *
 * Owner-only. Returns the decrypted TIN for display in the UI (masked as ***-**-XXXX).
 * The response NEVER returns plaintext TIN — only a display-safe masked string.
 * Full plaintext is only ever used by the PDF worker.
 *
 * Rate-limited conceptually: every access is audit-logged.
 */
export async function POST(_req: NextRequest, ctx: RouteContext) {
  const { id: artistId } = await ctx.params
  const supabase = await createClient()

  const { data: { user }, error: authErr } = await supabase.auth.getUser()
  if (authErr || !user) return Response.json({ error: 'Unauthorized' }, { status: 401 })

  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()
  if (!member) return Response.json({ error: 'No studio membership' }, { status: 403 })

  // Decrypt is owner-only
  if (member.role !== 'owner') {
    return Response.json({ error: 'Only studio owners can view TIN details' }, { status: 403 })
  }

  const { data: sub } = await supabase
    .from('subscriptions')
    .select('plan_tier')
    .eq('studio_id', member.studio_id)
    .eq('status', 'active')
    .maybeSingle()
  const plan = (sub?.plan_tier ?? 'solo') as PlanTier
  const guard = requireFeature(plan, 'payroll')
  if (guard) return guard

  const tinGuard = await requireTinKey()
  if (tinGuard) return tinGuard

  const { data, error } = await supabase.rpc('decrypt_artist_tin', {
    p_artist_id: artistId,
  })

  if (error) {
    logger.error({ err: error, artistId }, 'decrypt_artist_tin failed')
    return Response.json({ error: 'Failed to decrypt TIN' }, { status: 500 })
  }

  // Audit every access — do not skip even on success
  await logAuditAction(
    user.id,
    'tax_info.tin_viewed',
    `artist:${artistId}`,
    { artist_id: artistId, studio_id: member.studio_id },
    member.studio_id,
  )

  // data is the decrypted TIN string. Mask it before returning to client.
  // Full plaintext stays server-side. UI shows: ***-**-XXXX or **-*******
  const tin = typeof data === 'string' ? data : ''
  const masked =
    tin.length === 9
      ? `***-**-${tin.slice(-4)}`   // SSN: 9 digits
      : `**-${tin.slice(2, 5)}****` // EIN: 9 digits, different format

  return Response.json({ masked })
}

